package millhint

import "strings"

// Trim removes the optional +tail from a module token.
func Trim(tok string) string {
	tok = strings.TrimSpace(tok)
	if i := strings.IndexByte(tok, '+'); i >= 0 {
		return tok[:i]
	}
	return tok
}
EOF
