package spoolkit

import (
	"strings"

	"loft.local/wickpane/celltyp"
	"loft.local/wickpane/millhint"
)

// Clip normalizes fields used by the pane renderer.
func Clip(rows []celltyp.Row) []celltyp.Row {
	out := make([]celltyp.Row, 0, len(rows))
	for _, r := range rows {
		out = append(out, celltyp.Row{
			Kind: strings.TrimSpace(r.Kind),
			Mod:  millhint.Trim(r.Mod),
			Fn:   strings.TrimSpace(r.Fn),
		})
	}
	return out
}
EOF
