package wicksrc

import "loft.local/wickpane/celltyp"

// Nest removes fold records. A fold belongs to the following named frame and
// therefore never contributes a pane chunk of its own.
func Nest(rows []celltyp.Row) []celltyp.Row {
	out := make([]celltyp.Row, 0, len(rows))
	for _, r := range rows {
		if r.Kind == "i" {
			continue
		}
		out = append(out, r)
	}
	return out
}
EOF
