package pantryc

import (
	"loft.local/wickpane/celltyp"
	"loft.local/wickpane/millhint"
)

// Drop removes kernel helper frames which are not part of a pane.
func Drop(rows []celltyp.Row) []celltyp.Row {
	out := make([]celltyp.Row, 0, len(rows))
	for _, r := range rows {
		r.Mod = millhint.Trim(r.Mod)
		if r.Mod == "[vdso]" || r.Mod == "[vsyscall]" {
			continue
		}
		out = append(out, r)
	}
	return out
}
