package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"

	"loft.local/wickpane/pantryc"
	"loft.local/wickpane/spoolkit"
)

func stageFile(path string, data []byte) (string, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return "", err
	}
	f, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".*")
	if err != nil {
		return "", err
	}
	tmp := f.Name()
	ok := false
	defer func() {
		if !ok {
			f.Close()
			os.Remove(tmp)
		}
	}()
	if err = f.Chmod(0o644); err == nil {
		_, err = f.Write(data)
	}
	if err == nil {
		err = f.Sync()
	}
	if closeErr := f.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return "", err
	}
	ok = true
	return tmp, nil
}

func runBin() int {
	const dir = "/app/shardops/live"
	const outPath = "/app/shardops/bins.json"
	const pairPath = "/app/loomwell/pair.sha"

	entries, err := os.ReadDir(dir)
	if err != nil {
		return 1
	}
	out := make(map[string]string)
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".stk") {
			continue
		}
		rows, err := spoolkit.Scan(filepath.Join(dir, e.Name()))
		if err != nil {
			return 1
		}
		stem := strings.TrimSuffix(e.Name(), ".stk")
		out[stem] = pantryc.Join(pipeBack(pipeFront(rows)))
	}

	paneN, okN := out["n7"]
	paneS, okS := out["s7"]
	if !okN || !okS || paneN != paneS {
		return 1
	}
	blob, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return 1
	}
	blob = append(blob, '\n')
	sum := sha256.Sum256([]byte(paneN))
	pair := []byte(hex.EncodeToString(sum[:]) + "\n")

	outTmp, err := stageFile(outPath, blob)
	if err != nil {
		return 1
	}
	defer os.Remove(outTmp)
	pairTmp, err := stageFile(pairPath, pair)
	if err != nil {
		return 1
	}
	defer os.Remove(pairTmp)
	if err := os.Rename(outTmp, outPath); err != nil {
		return 1
	}
	if err := os.Rename(pairTmp, pairPath); err != nil {
		return 1
	}
	return 0
}
EOF
